mapper.select:
select count(1)
from daily_train_seat
where daily_train_id = #{dailyTrainId,jdbcType=BIGINT}

select

from daily_train_seat s
left join train_order o on o.daily_train_id = s.daily_train_id and o.status = '1'
left join train_order_item oi on oi.order_id = o.id and oi.daily_train_seat_id = s.id
  and oi.depart_index <= #{arriveIndex,jdbcType=INTEGER}
  and oi.arrive_index >= #{departIndex,jdbcType=INTEGER}
where s.daily_train_id = #{dailyTrainId,jdbcType=BIGINT}
  and s.sale_status = '0'
  and s.seat_type = #{seatType,jdbcType=CHAR}
  and oi.id is null
order by s.carriage_id, s.seat_index, s.seat_label
limit #{limit,jdbcType=INTEGER}

